        private static Dictionary<string, string> Parse(string raw)
        {
            var result = new Dictionary<string, string>();
            foreach (var item in raw.Split(';'))
            {
                var paire = item.Split(new[] { '=' }, 2);
                if (paire.Length == 2)
                {
                    result[paire[0]] = paire[1];
                }
            }
            return result;
        }

        public static string NomCommune(string code)
        {
            if (code != null && _communes.TryGetValue(code, out var nom)) return nom;
            return code;
        }

        public static string NomFokontany(string code)
        {
            if (code != null && _fokontany.TryGetValue(code, out var nom)) return nom;
            return code;
        }
